# clean-ancilla C3X sketch
# ccx(c1,c2,anc); ccx(anc,c3,target); ccx(c1,c2,anc)  # uncompute
def c3x_toffoli_budget():
    return {'toffolis': 3, 'ancillas': 1}

import numpy as np
def rxx(theta):
    c, s = np.cos(theta/2), -1j*np.sin(theta/2)
    return np.array([[c,0,0,s],[0,c,s,0],[0,s,c,0],[s,0,0,c]])

import numpy as np
def ryy(theta):
    c, s = np.cos(theta/2), 1j*np.sin(theta/2)
    return np.array([[c,0,0,s],[0,c,-s,0],[0,-s,c,0],[s,0,0,c]])

import numpy as np
def rzz(theta):
    p, m = np.exp(-1j*theta/2), np.exp(1j*theta/2)
    return np.diag([p, m, m, p])

import numpy as np
def u3(theta, phi, lam):
    c, s = np.cos(theta/2), np.sin(theta/2)
    return np.array([[c, -np.exp(1j*lam)*s],
                     [np.exp(1j*phi)*s, np.exp(1j*(phi+lam))*c]])

import numpy as np
def u2(phi, lam):
    r = 1/np.sqrt(2)
    return r*np.array([[1, -np.exp(1j*lam)],
                       [np.exp(1j*phi), np.exp(1j*(phi+lam))]])

import numpy as np
def u1(lam):
    return np.array([[1, 0], [0, np.exp(1j*lam)]])

import numpy as np
def global_phase(gamma, n=1):
    return np.exp(1j*gamma)*np.eye(2**n)

def sk_recurse(U, n, base_approx, gc_decompose):
    if n == 0:
        return base_approx(U)
    Un1 = sk_recurse(U, n-1, base_approx, gc_decompose)
    V, W = gc_decompose(U @ Un1.conj().T)
    Vn1 = sk_recurse(V, n-1, base_approx, gc_decompose)
    Wn1 = sk_recurse(W, n-1, base_approx, gc_decompose)
    return Vn1 @ Wn1 @ Vn1.conj().T @ Wn1.conj().T @ Un1

import numpy as np
def ccp(lam):
    d = np.ones(8, dtype=complex)
    d[7] = np.exp(1j*lam)
    return np.diag(d)

# multi-qubit ZZ...Z phase as CNOT ladder + RZ
# for i in 1..k-1: cnot(q[i] -> q[k])
# rz(theta) on q[k]
# for i in k-1..1: cnot(q[i] -> q[k])
def parity_ladder_cnots(k):
    return 2*(k-1)

# Margolus: ~3 CNOTs + Ry rotations vs 6 CNOTs for Toffoli
def cnot_savings():
    return {'toffoli': 6, 'margolus': 3}

import numpy as np
def zyz_angles(U):
    beta = 2*np.arccos(min(1.0, abs(U[0,0])))
    if np.sin(beta/2) > 1e-9:
        alpha = np.angle(U[1,1]) - np.angle(U[1,0])
        gamma = np.angle(U[1,1]) + np.angle(U[1,0])
    else:
        alpha = np.angle(U[1,1]) - np.angle(U[0,0]); gamma = 0.0
    return alpha, beta, gamma

import math
def rz_t_count(epsilon):
    # near-optimal Clifford+T T-count for a single RZ(theta)
    return round(3*math.log2(1/epsilon))
print(rz_t_count(1e-10))

def qsd_cnot_estimate(n):
    # leading-order CNOT count for generic n-qubit unitary
    return round((23/48)*4**n - (3/2)*2**n + 4/3)
print(qsd_cnot_estimate(3))
